    SELECT p.id, p.encontroId, p.participanteId, p.origem, p.lidoEm, p.registradaEm, p.justificativa
    FROM presencas p
    JOIN usuarios u ON u.id = p.participanteId
    WHERE p.encontroId = ?
    ORDER BY u.nome COLLATE NOCASE, p.participanteId
